package com.vit.archds.service;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import com.vit.archds.dto.ProjectDtos.*; import com.vit.archds.entity.*; import com.vit.archds.repository.*; import com.vit.archds.security.CurrentUserProvider; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ProjectService { private final ProjectRepository projects; private final RequirementRepository requirements; private final AuditLogRepository audit; private final AnalysisJobRepository jobs; private final ArchitectureCandidateRepository candidates; private final DecisionRepository decisions; private final CurrentUserProvider current; private final ObjectMapper mapper; public ProjectService(ProjectRepository p,RequirementRepository r,AuditLogRepository a,CurrentUserProvider c,ObjectMapper m,AnalysisJobRepository j,ArchitectureCandidateRepository ca,DecisionRepository d){projects=p;requirements=r;audit=a;current=c;mapper=m;jobs=j;candidates=ca;decisions=d;}
 @Transactional public Project create(CreateProject d){User u=current.require();Project p=projects.save(new Project(d.name().trim(),d.description(),u));audit.save(new AuditLog(u,"PROJECT_CREATED","PROJECT",String.valueOf(p.getId())));return p;}
 public List<Project> all(){return projects.findByOwnerOrderByUpdatedAtDesc(current.require());}
 public Project get(long id){return projects.findByIdAndOwner(id,current.require()).orElseThrow(()->new NoSuchElementException("Project not found"));}
 @Transactional public void delete(long id){Project p=get(id);for(AnalysisJob j:jobs.findByProjectOrderByCreatedAtDesc(p)){candidates.deleteAll(candidates.findByJob(j));jobs.delete(j);}requirements.findTopByProjectOrderByCreatedAtDesc(p).ifPresent(requirements::delete);decisions.deleteAll(decisions.findByProject(p));projects.delete(p);audit.save(new AuditLog(current.require(),"PROJECT_DELETED","PROJECT",String.valueOf(id)));}
 @Transactional public Requirement saveRequirements(long id,Requirements d){Project p=get(id);if(d.qualityWeights()==null||d.qualityWeights().size()<2||d.qualityWeights().values().stream().anyMatch(v->v<0)||d.qualityWeights().values().stream().mapToInt(Integer::intValue).sum()!=100)throw new IllegalArgumentException("Quality weights must be non-negative and sum to 100");try{String w=mapper.writeValueAsString(d.qualityWeights());Requirement r=new Requirement(p,d.functionalRequirements(),d.nonFunctionalRequirements(),d.constraints(),d.technologyPreferences(),d.expectedUsers(),d.budget(),w,d.alternatives(),d.maxIterations());Requirement saved=requirements.save(r);audit.save(new AuditLog(current.require(),"REQUIREMENTS_SAVED","PROJECT",String.valueOf(id)));return saved;}catch(JsonProcessingException e){throw new IllegalStateException("Unable to serialize quality weights");}}
 public Requirement latestRequirement(long id){Project p=get(id);return requirements.findTopByProjectOrderByCreatedAtDesc(p).orElseThrow(()->new NoSuchElementException("Requirements not found"));}}
